"use client";

import "../../styles/whatiuse-base.css";
import "../../styles/components/sheet.css";
import { Dialog as DialogPrimitive } from "@base-ui/react/dialog";
import { X } from "@phosphor-icons/react";
import type { ComponentPropsWithRef } from "react";
import { cn } from "../../lib/cn";
import { IconButton } from "./icon-button";

export const Sheet = DialogPrimitive.Root;
export const SheetTrigger = DialogPrimitive.Trigger;
export const SheetClose = DialogPrimitive.Close;
export const SheetTitle = DialogPrimitive.Title;
export const SheetDescription = DialogPrimitive.Description;

export type SheetSide = "top" | "right" | "bottom" | "left";
export type SheetContentProps = DialogPrimitive.Popup.Props & {
  side?: SheetSide;
  showClose?: boolean;
};

export function SheetContent({ className, children, side = "right", showClose = true, ...props }: SheetContentProps) {
  return (
    <DialogPrimitive.Portal>
      <DialogPrimitive.Backdrop className="whatiuse-sheet__backdrop" />
      <DialogPrimitive.Viewport className="whatiuse-sheet__viewport" data-side={side}>
        <DialogPrimitive.Popup className={cn("whatiuse-sheet", className)} data-side={side} data-layer="modal" {...props}>
          {children}
          {showClose && (
            <DialogPrimitive.Close render={<IconButton className="whatiuse-sheet__close" variant="ghost" size="small" aria-label="Close panel" />}>
              <X />
            </DialogPrimitive.Close>
          )}
        </DialogPrimitive.Popup>
      </DialogPrimitive.Viewport>
    </DialogPrimitive.Portal>
  );
}

export function SheetHeader({ className, ...props }: ComponentPropsWithRef<"div">) {
  return <div className={cn("whatiuse-sheet__header", className)} {...props} />;
}

export function SheetBody({ className, ...props }: ComponentPropsWithRef<"div">) {
  return <div className={cn("whatiuse-sheet__body", className)} {...props} />;
}

export function SheetFooter({ className, ...props }: ComponentPropsWithRef<"div">) {
  return <div className={cn("whatiuse-sheet__footer", className)} {...props} />;
}

/* Generated from src/foundation.css and src/styles.css. Do not edit directly. */

@layer whatiuse.tokens, whatiuse.base, whatiuse.components;

@layer whatiuse.components {
.whatiuse-sheet__backdrop {
  position: fixed;
  inset: 0;
  z-index: var(--whatiuse-layer-modal-backdrop);
  background: var(--whatiuse-bg-scrim);
  backdrop-filter: blur(1.5px);
  transition: opacity var(--whatiuse-enter-duration) var(--whatiuse-ease-out);
}

.whatiuse-sheet__backdrop[data-starting-style],
.whatiuse-sheet__backdrop[data-ending-style] { opacity: 0; }

.whatiuse-sheet__backdrop[data-ending-style] { transition-duration: var(--whatiuse-exit-duration); }

.whatiuse-sheet__viewport {
  position: fixed;
  inset: 0;
  z-index: var(--whatiuse-layer-modal);
  display: flex;
  pointer-events: none;
}

.whatiuse-sheet__viewport[data-side="right"] { justify-content: flex-end; }

.whatiuse-sheet__viewport[data-side="left"] { justify-content: flex-start; }

.whatiuse-sheet__viewport[data-side="top"] { align-items: flex-start; }

.whatiuse-sheet__viewport[data-side="bottom"] { align-items: flex-end; }

.whatiuse-sheet {
  position: relative;
  display: flex;
  width: min(380px, calc(100vw - 16px));
  height: 100%;
  flex-direction: column;
  overflow: hidden;
  outline: 0;
  background: var(--whatiuse-bg-modal);
  box-shadow: var(--whatiuse-shadow-modal);
  pointer-events: auto;
  transition: opacity var(--whatiuse-enter-duration) var(--whatiuse-ease-out), transform var(--whatiuse-enter-duration) var(--whatiuse-ease-drawer);
}

.whatiuse-sheet[data-side="right"] { border-radius: 12px 0 0 12px; }

.whatiuse-sheet[data-side="left"] { border-radius: 0 12px 12px 0; }

.whatiuse-sheet[data-side="top"],
.whatiuse-sheet[data-side="bottom"] { width: 100%; height: min(360px, 70vh); }

.whatiuse-sheet[data-side="top"] { border-radius: 0 0 12px 12px; }

.whatiuse-sheet[data-side="bottom"] { border-radius: 12px 12px 0 0; }

.whatiuse-sheet[data-side="right"][data-starting-style],
.whatiuse-sheet[data-side="right"][data-ending-style] { opacity: .72; transform: translateX(18px); }

.whatiuse-sheet[data-side="left"][data-starting-style],
.whatiuse-sheet[data-side="left"][data-ending-style] { opacity: .72; transform: translateX(-18px); }

.whatiuse-sheet[data-side="top"][data-starting-style],
.whatiuse-sheet[data-side="top"][data-ending-style] { opacity: .72; transform: translateY(-18px); }

.whatiuse-sheet[data-side="bottom"][data-starting-style],
.whatiuse-sheet[data-side="bottom"][data-ending-style] { opacity: .72; transform: translateY(18px); }

.whatiuse-sheet[data-ending-style] { transition-duration: var(--whatiuse-exit-duration); transition-timing-function: var(--whatiuse-ease-out); }

.whatiuse-sheet__close { position: absolute; top: 14px; right: 14px; }

.whatiuse-sheet__header { display: grid; gap: 6px; padding: 20px 52px 16px 20px; }

.whatiuse-sheet__header [data-slot="dialog-title"],
.whatiuse-sheet__header h2 { margin: 0; font-size: 17px; font-weight: 600; letter-spacing: -.018em; }

.whatiuse-sheet__header [data-slot="dialog-description"],
.whatiuse-sheet__header p { margin: 0; color: var(--whatiuse-fg-muted); font-size: var(--whatiuse-type-ui); line-height: 1.5; }

.whatiuse-sheet__body { display: grid; min-height: 0; flex: 1 1 auto; align-content: start; gap: 16px; overflow: auto; padding: 8px 20px 24px; }

.whatiuse-sheet__footer { display: flex; flex: 0 0 auto; justify-content: flex-end; gap: 6px; padding: 14px 20px 16px; background: color-mix(in oklch, var(--whatiuse-bg-modal) 92%, transparent); box-shadow: 0 -1px 0 var(--whatiuse-separator); }

@media (prefers-reduced-motion: reduce) {
.whatiuse-sheet,
.whatiuse-sheet__backdrop { transition-duration: 0.01ms; }

.whatiuse-sheet[data-starting-style],
.whatiuse-sheet[data-ending-style] { transform: none; }
}
}
